        <?php if(in_array($slug,['instagram','tiktok','youtube'],true)):?><div class="field"><label for="buffer-mode-<?=e($slug)?>">Buffer delivery mode</label><select name="buffer_mode" id="buffer-mode-<?=e($slug)?>"><option value="automatic" <?=$channel['buffer_mode']==='automatic'?'selected':''?>>Automatic publishing</option><option value="notification" <?=$channel['buffer_mode']==='notification'?'selected':''?>>Mobile notification — finish in the app</option></select></div><?php endif;?>
